-- 423: WASSCE English comprehension multiple-choice set A (batch sprint 1).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_423_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_423_guard;
INSERT INTO _migration_423_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_cmp_mcq_001' AND NOT (q.topic_id IS 'topic_wassce_english_comprehension' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the harmattan came, Kofi''s grandfather was ready. He had sealed the windows with old newspapers and moved his seedlings into the shade of the mango tree. "The wind respects the prepared," he said. When the haze lifted, his was the only garden on the street still green." According to the passage, Kofi''s grandfather sealed the windows with what material?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. old newspapers","B. wet towels","C. wooden boards","D. plastic sheets"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The passage states directly that he "had sealed the windows with old newspapers". The other materials are not mentioned anywhere in the passage.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_cmp_mcq_001' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_423_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_cmp_mcq_002' AND NOT (q.topic_id IS 'topic_wassce_english_comprehension' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the harmattan came, Kofi''s grandfather was ready. He had sealed the windows with old newspapers and moved his seedlings into the shade of the mango tree. "The wind respects the prepared," he said. When the haze lifted, his was the only garden on the street still green." Where did the grandfather move his seedlings?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. behind the house","B. into the shade of the mango tree","C. onto the street","D. into the kitchen"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The passage says he "moved his seedlings into the shade of the mango tree". None of the other locations is mentioned.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_cmp_mcq_002' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_423_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_cmp_mcq_003' AND NOT (q.topic_id IS 'topic_wassce_english_comprehension' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the harmattan came, Kofi''s grandfather was ready. He had sealed the windows with old newspapers and moved his seedlings into the shade of the mango tree. "The wind respects the prepared," he said. When the haze lifted, his was the only garden on the street still green." The saying "The wind respects the prepared" suggests that' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. the wind avoids only wealthy households","B. preparation can stop the harmattan from blowing","C. hardship has less power over people who make ready for it","D. the wind is a person who greets the elders"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The saying is figurative: the prepared suffer less from hardship, as the grandfather''s intact garden shows. It does not claim the wind is literally a person.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Interpret' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_cmp_mcq_003' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_423_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_cmp_mcq_004' AND NOT (q.topic_id IS 'topic_wassce_english_comprehension' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the harmattan came, Kofi''s grandfather was ready. He had sealed the windows with old newspapers and moved his seedlings into the shade of the mango tree. "The wind respects the prepared," he said. When the haze lifted, his was the only garden on the street still green." The grandfather''s actions show that he was' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. afraid of his neighbours","B. wasteful with his property","C. indifferent to the weather","D. foresighted and careful"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Sealing windows and sheltering seedlings before the wind arrived show planning and care; nothing suggests fear of neighbours, waste, or indifference.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Interpret' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_cmp_mcq_004' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_423_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_cmp_mcq_005' AND NOT (q.topic_id IS 'topic_wassce_english_comprehension' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the harmattan came, Kofi''s grandfather was ready. He had sealed the windows with old newspapers and moved his seedlings into the shade of the mango tree. "The wind respects the prepared," he said. When the haze lifted, his was the only garden on the street still green." The last sentence implies that the other people on the street' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. had not prepared for the harmattan as well as the grandfather","B. had planted no gardens at all","C. envied the grandfather''s mango tree","D. had left the street before the harmattan"]' AND q.correct_answer IS 'A' AND q.explanation IS 'His garden was the only one still green, and the passage ties his success to preparation; the implied contrast is that the others had not prepared as well.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Infer' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_cmp_mcq_005' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
